"use strict";

/**
 * Utility function to get the current page name.
 */
const getPageName = () =>
  window.location.pathname.split("/").pop() || "index.html";

/**
 * Safely fetches and injects HTML into the target element if it's empty.
 * @param {string} url - Path to the HTML file.
 * @param {string} selector - CSS selector of the target element.
 * @param {Function} callback - Optional function to run after insertion.
 */
const loadHTML = async (url, selector, callback) => {
  const element = document.querySelector(selector);

  // 🔒 Prevent duplicate injection
  if (!element || element.dataset.loaded) {
    callback?.(); // Run callback even if no injection is needed
    return;
  }

  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`Failed to load ${url}`);

    element.innerHTML = await response.text();
    element.dataset.loaded = "true"; // ✅ Mark as loaded
    callback?.();
  } catch (error) {
    console.error(`❌ Error loading ${url}:`, error);
  }
};

/**
 * Highlights the current navigation link.
 */
const navHighlights = () => {
  const page = getPageName().toLowerCase();

  document.querySelectorAll(".nav-btn").forEach((link) => {
    link.removeAttribute("aria-current");
    link.classList.remove("active");

    const href = link
      .getAttribute("href")
      ?.replace(/^\.?\//, "")
      .toLowerCase();
    const isHomePage =
      (page === "index.html" || page === "") && href.includes("index.html");
    const isMatchingPage = page === href;

    if (isHomePage || isMatchingPage) {
      link.setAttribute("aria-current", "page");
      link.classList.add("active");
    }
  });
};

/**
 * Toggles the dropdown menu.
 */
const setupDropdown = () => {
  const toggleBtn = document.querySelector(".toggle-btn");
  const dropDown = document.querySelector(".dropdown-menu");
  const bars = document.querySelector("#bars");

  if (!toggleBtn || !dropDown || !bars) return;

  toggleBtn.removeEventListener("click", toggleBtn._clickHandler);

  toggleBtn._clickHandler = () => {
    dropDown.classList.toggle("open");
    bars.className = dropDown.classList.contains("open")
      ? "fa-solid fa-beat fa-xmark"
      : "fa-bars fa-beat fa-solid";
  };

  toggleBtn.addEventListener("click", toggleBtn._clickHandler);
};

/**
 * Opens the modal window.
 */
const modalWindow = (e) => {
  const img = e.target.closest("img");
  const modal = document.getElementById("modalBox");
  const modalImage = document.getElementById("modal-image");

  if (img && modal && modalImage) {
    modal.style.display = "flex";
    modalImage.src = img.src;
  }
};

/**
 * Closes the modal window.
 */
const closeModal = (e) => {
  const modal = document.getElementById("modalBox");
  const exitButton = document.querySelector(".close");

  if (modal && (e.target === modal || e.target === exitButton)) {
    modal.style.display = "none";
  }
};

/**
 * Initialization after DOM content is loaded.
 */
window.addEventListener("DOMContentLoaded", async () => {
  const page = getPageName();
  const pagesWithDynamicHeaderFooter = [
    "story.html",
    "work.html",
    "contact.html",
  ];

  if (pagesWithDynamicHeaderFooter.includes(page)) {
    // Only inject header/footer if they're empty and not loaded before
    await loadHTML("./header.html", "header", () => {
      navHighlights();
      setupDropdown();
    });

    await loadHTML("./footer.html", "footer");
  } else {
    // For pages like index.html with static header/footer
    navHighlights();
    setupDropdown();
  }

  // Modal setup for story page only
  if (page === "story.html") {
    document.querySelector("section")?.addEventListener("click", modalWindow);
  }

  document.addEventListener("click", closeModal);
});
